import React, { useId } from 'react';

interface RadarIconProps {
  size?: number;
  className?: string;
}

/**
 * Pixel-accurate SVG representation of the procedural 32x32 tray, window & exe icon
 * generated by radar_icon_rgba() in src/main.rs and build.rs
 * (True AMOLED Black #000000 -> #0A080E fill, diagonal Pink #FF4D94 -> Blush #FFA6D2 -> Pearl White #FFF5FA border, V & radar dot).
 */
export const RadarIcon: React.FC<RadarIconProps> = ({ size = 28, className = '' }) => {
  const uid = useId().replace(/:/g, '');
  const bgId = `radar-bg-${uid}`;
  const gradId = `radar-pw-${uid}`;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 32 32"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-hidden="true"
    >
      <defs>
        <linearGradient id={bgId} x1="0" y1="0" x2="0" y2="32" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#000000" />
          <stop offset="100%" stopColor="#0A080E" />
        </linearGradient>
        <linearGradient id={gradId} x1="0" y1="32" x2="32" y2="0" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#FF4D94" />
          <stop offset="55%" stopColor="#FFA6D2" />
          <stop offset="100%" stopColor="#FFF5FA" />
        </linearGradient>
      </defs>
      <rect width="32" height="32" rx="3" fill={`url(#${bgId})`} />
      <rect x="1" y="1" width="30" height="30" rx="2.2" stroke={`url(#${gradId})`} strokeWidth="2" />
      <path
        d="M7.5 8.5H11.6L16 20.4L20.4 8.5H24.5L17.9 24.8H14.1L7.5 8.5Z"
        fill={`url(#${gradId})`}
      />
      <circle cx="16" cy="9" r="2.2" fill="#FFF5FA" />
    </svg>
  );
};
